IF NOT EXISTS (
    SELECT * FROM [__EFMigrationsHistory]
    WHERE [MigrationId] = N'20251105032623_SeedWarehouseQuantities'
)
BEGIN
                    INSERT INTO WarehouseQuantities (
                        Id, 
                        InventoryItemId, 
                        WarehouseId, 
                        CurrentStock, 
                        AvailableStock, 
                        AllocatedStock, 
                        ReorderLevel,
                        MaxStock,
                        AverageCost,
                        CreatedAt, 
                        IsDeleted, 
                        TenantId
                    )
                    SELECT 
                        NEWID() AS Id,
                        i.Id AS InventoryItemId,
                        '11111111-1111-1111-1111-111111111111' AS WarehouseId, -- Main Warehouse
                        i.CurrentStock,
                        i.AvailableStock,
                        i.AllocatedStock,
                        i.ReorderLevel,
                        i.MaximumLevel AS MaxStock,
                        i.AverageCost,
                        GETUTCDATE() AS CreatedAt,
                        0 AS IsDeleted,
                        i.TenantId
                    FROM InventoryItems i
                    WHERE i.IsDeleted = 0
                      AND NOT EXISTS (
                          SELECT 1 FROM WarehouseQuantities wq 
                          WHERE wq.InventoryItemId = i.Id 
                            AND wq.WarehouseId = '11111111-1111-1111-1111-111111111111'
                      )
END;
GO

